import { HttpStatus, ParseUUIDPipe } from '@nestjs/common';

/**
 * Route `:id` pipe. Every id in this service is a UUID v4 generated by the
 * server, so a malformed id can never match a record. The task says an unknown
 * id is a 404, so a malformed one is reported the same way instead of 400.
 */
export const parseIdPipe = new ParseUUIDPipe({
  version: '4',
  errorHttpStatusCode: HttpStatus.NOT_FOUND,
});
